# bash completion for checkbox-cli
# Generated by `checkbox-cli completion bash`, do not edit.

_checkbox_cli_fetch() {
    sh -c 'ids=$("$0" __complete "$1" 2>/dev/null) && [ -n "$ids" ] || exit 0; printf "%s\n" "$ids"; mkdir -p "${2%/*}" 2>/dev/null && printf "%s\n" "$ids" 2>/dev/null > "$2.$$" && mv -f "$2.$$" "$2" 2>/dev/null || rm -f "$2.$$" 2>/dev/null; exit 0' "$@"
}

_checkbox_cli_dynamic() {
    local cmd="${COMP_WORDS[0]}" file
    if [ -n "$SNAP" ] && [ -x "$SNAP/bin/checkbox-cli-wrapper" ]; then
        cmd="$SNAP/bin/checkbox-cli-wrapper"
    fi
    file="${XDG_CACHE_HOME:-$HOME/.cache}/checkbox/completion/${COMP_WORDS[0]##*/}.$1"
    if [ -s "$file" ]; then
        cat "$file"
        if [ -z "$(find "$file" -mmin -1 2>/dev/null)" ]; then
            touch "$file" 2>/dev/null
            _checkbox_cli_fetch "$cmd" "$1" "$file" </dev/null >/dev/null 2>&1 &
        fi
    else
        _checkbox_cli_fetch "$cmd" "$1" "$file"
    fi
}

_checkbox_cli_words() {
    local word ucur=${cur//\\/}
    ucur=${ucur#[\"\']}
    while IFS= read -r word; do
        if [[ -n $word && $word == "$ucur"* ]]; then
            if [[ $cur == [\"\']* ]]; then
                COMPREPLY+=("$word")
            else
                COMPREPLY+=("$(printf '%q' "$word")")
            fi
        fi
    done <<< "$1"
}

_checkbox_cli_files() {
    if declare -F _filedir >/dev/null; then
        _filedir
    else
        compopt -o filenames 2>/dev/null
        local IFS=$'\n'
        COMPREPLY+=($(compgen -f -- "$cur"))
    fi
}

_checkbox_cli() {
    local cur prev words cword
    COMPREPLY=()
    if declare -F _get_comp_words_by_ref >/dev/null; then
        _get_comp_words_by_ref -n : cur prev words cword
    else
        words=("${COMP_WORDS[@]}")
        cword=$COMP_CWORD
        cur="${words[cword]}"
        prev="${words[cword-1]}"
    fi

    local cmd="" i
    for ((i = 1; i < cword; i++)); do
        case "${words[i]}" in
            -*) continue ;;
            master) cmd=control ;;
            remote) cmd=control ;;
            service) cmd=run-agent ;;
            slave) cmd=run-agent ;;
            config|check-config|launcher|list|run|startprovider|submit|show|list-bootstrapped|expand|merge-reports|merge-submissions|tp-export|run-agent|control|translate|completion) cmd="${words[i]}" ;;
            *) cmd=launcher ;;
        esac
        break
    done

    local opts="" values="" kind=""
    case "$cmd" in
        '')
            opts='-h
--help
-v
--verbose
--debug
--clear-cache
--clear-old-sessions
--version'
            values='config
check-config
launcher
list
run
startprovider
submit
show
list-bootstrapped
expand
merge-reports
merge-submissions
tp-export
run-agent
control
translate
completion'
            kind=file
            ;;
        config)
            opts='-h
--help'
            values='check
defaults'
            ;;
        check-config)
            opts='-h
--help'
            kind=file
            ;;
        launcher)
            case "$prev" in
                --title) :; return 0 ;;
                -m|--message) :; return 0 ;;
            esac
            opts='-h
--help
--verify
--title
-m
--message
--dont-suppress-output
-v
--verbose
--debug
--clear-cache
--clear-old-sessions
--version'
            kind=file
            ;;
        list)
            case "$prev" in
                -f|--format) :; return 0 ;;
            esac
            opts='-h
--help
-a
--attrs
-f
--format'
            values='category
exporter
job
manifest entry
packaging meta-data
template
test plan
file
provider
storage
service
all-jobs'
            ;;
        run)
            case "$prev" in
                -f|--output-format) :; return 0 ;;
                -p|--output-options) :; return 0 ;;
                -o|--output-file) _checkbox_cli_files; return 0 ;;
                -t|--transport) _checkbox_cli_words 'file
stream
submission-service'; return 0 ;;
                --transport-where) :; return 0 ;;
                --transport-options) :; return 0 ;;
                --title) :; return 0 ;;
                -m|--message) :; return 0 ;;
            esac
            opts='-h
--help
--non-interactive
-f
--output-format
-p
--output-options
-o
--output-file
-t
--transport
--transport-where
--transport-options
--title
-m
--message
--exact'
            kind=units
            ;;
        startprovider)
            opts='-h
--help
--empty'
            ;;
        submit)
            case "$prev" in
                -m|--message) :; return 0 ;;
            esac
            opts='-h
--help
-s
--staging
-m
--message'
            kind=file
            ;;
        show)
            opts='-h
--help
--exact'
            kind=units
            ;;
        list-bootstrapped)
            case "$prev" in
                -f|--format) :; return 0 ;;
                --normal-user) :; return 0 ;;
            esac
            opts='-h
--help
--exact
-f
--format
--normal-user'
            kind=test-plans
            ;;
        expand)
            case "$prev" in
                -f|--format) :; return 0 ;;
            esac
            opts='-h
--help
-f
--format
--exact'
            kind=test-plans
            ;;
        merge-reports)
            case "$prev" in
                -o|--output-file) _checkbox_cli_files; return 0 ;;
            esac
            opts='-h
--help
-o
--output-file'
            kind=file
            ;;
        merge-submissions)
            case "$prev" in
                -o|--output-file) _checkbox_cli_files; return 0 ;;
                --title) :; return 0 ;;
            esac
            opts='-h
--help
-o
--output-file
--title'
            kind=file
            ;;
        tp-export)
            opts='-h
--help
-n
--nofake'
            kind=test-plans
            ;;
        run-agent)
            case "$prev" in
                --port) :; return 0 ;;
                --log-level) _checkbox_cli_words 'DEBUG
INFO
WARNING'; return 0 ;;
            esac
            opts='-h
--help
--resume
--port
--log-level'
            ;;
        control)
            case "$prev" in
                --port) :; return 0 ;;
                -u|--user) :; return 0 ;;
            esac
            opts='-h
--help
--port
-u
--user
--clean'
            kind=file
            ;;
        translate)
            opts='-h
--help'
            kind=file
            ;;
        completion)
            opts='-h
--help'
            values='bash
zsh
fish'
            ;;
    esac

    if [[ $cur == -* ]]; then
        _checkbox_cli_words "$opts"
    else
        _checkbox_cli_words "$values"
        case "$kind" in
            file) _checkbox_cli_files ;;
            test-plans|units) _checkbox_cli_words "$(_checkbox_cli_dynamic "$kind")" ;;
        esac
    fi
    if declare -F __ltrim_colon_completions >/dev/null; then
        __ltrim_colon_completions "$cur"
    fi
    return 0
}

complete -F _checkbox_cli checkbox-cli checkbox.checkbox-cli
